6	/** The cart, persisted in the `cart` cookie. Overrides the base layer's legacy `useCart`. */
7	export function useCart() {
8	  const lines = useCookie<CartLine[]>('cart', { default: () => [] })
9	  const count = computed(() => sumBy(lines.value, line => line.qty))
10	  function add(slug: string, qty = 1) {
11	    const existing = lines.value.find(line => line.slug === slug)
12	    lines.value = existing
13	      ? lines.value.map(line => (line.slug === slug ? { ...line, qty: line.qty + qty } : line))
14	      : [...lines.value, { slug, qty }]
15	  }
16	  function remove(slug: string) {
17	    lines.value = lines.value.filter(line => line.slug !== slug)
18	  }
19	  return { lines, count, add, remove }
20	}
